/**
 * Shader des vagues de degrade.
 *
 * ## L'idee mathematique
 *
 * Un degrade repete en bandes horizontales — fond, premiere teinte,
 * seconde teinte, fond — dont la hauteur est deplacee par une houle. La
 * houle est une somme de sinus de l'abscisse, a frequences non multiples
 * et a vitesses opposees, pour qu'elle ne se referme jamais sur elle-meme.
 *
 * Ce qui distingue ces vagues des lignes ondulantes ou des tranches : il
 * n'y a ni trait ni marche, seulement des nappes de couleur qui glissent
 * l'une sur l'autre. La douceur regle la largeur des transitions : basse,
 * les bandes sont franches ; haute, elles se fondent en un seul degrade
 * qui ondule.
 *
 * ## Uniforms
 *
 * - `uTime` — temps en secondes, fourni par le moteur.
 * - `uResolution` — taille du canevas en pixels, fournie par le moteur.
 * - `uColorA` — le fond.
 * - `uColorB` — la premiere teinte des bandes.
 * - `uColorC` — la seconde teinte des bandes.
 * - `uBands` — nombre de bandes sur la hauteur.
 * - `uAmplitude` — hauteur de la houle, en fraction du cadre.
 * - `uSpeed` — vitesse de la houle.
 * - `uSoftness` — largeur des transitions.
 * - `uDetail` — nombre d'harmoniques de la houle, et donc son cout.
 */
export const GRADIENT_WAVES_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform float uBands;
uniform float uAmplitude;
uniform float uSpeed;
uniform float uSoftness;
uniform float uDetail;

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  float x = vUv.x * aspect;
  float t = uTime * uSpeed;
  int harmoniques = int(clamp(uDetail, 1.0, 3.0));

  // La houle : des sinus a frequences non multiples, aux vitesses opposees.
  float houle = sin(x * 2.4 + t);
  if (harmoniques >= 2) houle += 0.5 * sin(x * 4.1 - t * 1.3 + 1.0);
  if (harmoniques >= 3) houle += 0.25 * sin(x * 7.3 + t * 0.7 + 2.0);
  houle *= uAmplitude;

  // La bande : la hauteur deplacee, et une derive lente vers le haut.
  float phase = (vUv.y + houle) * max(uBands, 0.5) - uTime * 0.05;
  float w = fract(phase);

  // Le degrade repete : le fond en 0, la premiere teinte en un tiers, la
  // seconde en deux tiers, le fond en 1. La douceur elargit les paliers.
  float douceur = mix(0.06, 0.33, clamp(uSoftness, 0.0, 1.0));
  float kB = smoothstep(0.333 - douceur, 0.333, w) * smoothstep(0.666, 0.666 - douceur, w);
  float kC = smoothstep(0.666 - douceur, 0.666, w) * smoothstep(1.0, 1.0 - douceur, w);

  vec3 colour = mix(uColorA, uColorB, kB);
  colour = mix(colour, uColorC, kC);

  // La crete : la ou la houle culmine, la bande s'eclaire un peu.
  float crete = smoothstep(0.0, 1.0, houle / max(uAmplitude * 1.75, 0.0001));
  colour += mix(uColorB, uColorC, 0.5) * crete * 0.12 * max(kB, kC);

  gl_FragColor = vec4(clamp(colour, 0.0, 1.0), 1.0);
}
`

sources.component.tsx:
/**
 * Vagues de degrade : des bandes de degrade repete, sans trait ni marche, deplacees par une houle qui ne se referme jamais.
 *
 * ## Le principe
 *
 * Un degrade repete en bandes horizontales — fond, premiere teinte,
 * seconde teinte, fond — dont la hauteur est deplacee par une somme de
 * sinus a frequences non multiples et a vitesses opposees. Ni trait ni
 * marche : des nappes qui glissent l'une sur l'autre, et une douceur qui
 * va de bandes franches a un seul degrade ondulant.
 *
 * ## Ce que ce composant delegue
 *
 * Il ne porte que ce qui le distingue : son shader, ses reglages et son repli.
 * La lecture des tokens, leur conversion en flottants et leur relecture au
 * changement de theme viennent du moteur — les recopier ici en ferait autant
 * de versions a maintenir qu'il y a de fonds.
 *
 * Le repli n'est pas une precaution : il est affiche pendant le chargement du
 * backend, quand WebGL manque, quand l'arbitre refuse la surface — il n'en
 * accorde qu'une par backend — et sous mouvement reduit.
 *
 * @module
 */

import {
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { type ReactElement } from 'react'

import { GRADIENT_WAVES_FRAGMENT } from './gradient-waves.shader.js'

/** Ce que l'echappatoire recoit. */
export interface GradientWavesControls {
  /** Couleurs effectivement transmises au shader. */
  readonly colours: readonly ShaderColour[]
  /** Motif du refus, s'il y en a un. */
  readonly refused: string | undefined
}

/** Proprietes propres au composant. */
export interface GradientWavesOwnProps {
  /** Nombre de bandes sur la hauteur. @defaultValue 4 */
  bands?: number
  /** Hauteur de la houle, en fraction du cadre. @defaultValue 0.12 */
  amplitude?: number
  /** Vitesse de la houle. @defaultValue 0.4 */
  speed?: number
  /** Largeur des transitions. Bas, les bandes sont franches. @defaultValue 0.6 */
  softness?: number
  /** Tokens dont les couleurs sont lues. */
  colors?: readonly string[]
  /** Classes du repli. */
  fallback?: string
  /** Echappatoire. */
  onReady?: ReadyCallback<GradientWavesControls>
}

/** Toutes les proprietes. */
export type GradientWavesProps = Customisable<GradientWavesOwnProps>

/** Tokens employes par defaut : le fond, les deux teintes des bandes. */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-palette-indigo-400',
  '--o-palette-cyan-300',
] as const

/** Repli par defaut : un degrade fige, dans les memes tons. */
const DEFAULT_FALLBACK =
  'o-bg-gradient-to-b o-from-zinc-50 dark:o-from-zinc-950 o-via-indigo-200 dark:o-via-indigo-900 o-to-cyan-200 dark:o-to-cyan-900'

/**
 * Detail hors qualite basse.
 *
 * Le nombre de bandes est une frequence, pas une boucle. Ce sont les
 * harmoniques de la houle qui sont bornees.
 */
const DETAIL = 3

/** Detail en qualite basse. */
const LOW_DETAIL = 1

/**
 * Vagues de degrade.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <GradientWaves className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function GradientWaves({
  bands = 4,
  amplitude = 0.12,
  speed = 0.4,
  softness = 0.6,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: GradientWavesProps): ReactElement {
  const { ref, setHost, ready, refused, colours } = useTokenShader<HTMLDivElement>({
    fragment: GRADIENT_WAVES_FRAGMENT,
    colors,
    uniforms: {
      uBands: bands,
      uAmplitude: amplitude,
      uSpeed: speed,
      uSoftness: softness,
      uDetail: DETAIL,
    },
    name: 'gradient-waves',
    degrade: (quality) => ({
      uDetail: quality === 'low' ? LOW_DETAIL : DETAIL,
    }),
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
